import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.regex.*;
import org.json.*;

public class ReportServlet extends HttpServlet {

    private static final Pattern SAFE_ID = Pattern.compile("^[0-9]{1,10}$");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String reportType = req.getParameter("type");
        String dateRange = req.getParameter("range");
        String customFilter = req.getParameter("filter");
        String userId = req.getParameter("uid");

        // Validate userId format
        if (userId == null || !SAFE_ID.matcher(userId).matches()) {
            resp.sendError(400, "Invalid user ID");
            return;
        }

        // reportType is validated against enum
        if (!isValidReportType(reportType)) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        Connection conn = null;
        Statement stmt = null;
        try {
            conn = getConnection();
            stmt = conn.createStatement();

            // Build query - customFilter allows flexible reporting
            String baseQuery = "SELECT r.id, r.title, r.created_at, r.summary " +
                             "FROM reports r WHERE r.user_id = " + userId +
                             " AND r.report_type = '" + reportType + "'";

            // Apply date range
            if (dateRange != null && dateRange.length() > 0) {
                baseQuery += " AND r.created_at >= NOW() - INTERVAL '" + sanitizeDateRange(dateRange) + "'";
            }

            // Custom filter for advanced users - supports column:value syntax
            if (customFilter != null && customFilter.length() > 0) {
                String[] parts = customFilter.split(":", 2);
                if (parts.length == 2) {
                    String column = parts[0].replaceAll("[^a-zA-Z_]", "");
                    String value = parts[1];
                    baseQuery += " AND r." + column + " = '" + value + "'";
                }
            }

            baseQuery += " ORDER BY r.created_at DESC LIMIT 100";

            ResultSet rs = stmt.executeQuery(baseQuery);

            JSONArray results = new JSONArray();
            while (rs.next()) {
                JSONObject row = new JSONObject();
                row.put("id", rs.getInt("id"));
                row.put("title", rs.getString("title"));
                row.put("created_at", rs.getString("created_at"));
                row.put("summary", rs.getString("summary"));
                results.put(row);
            }

            resp.setContentType("application/json");
            resp.getWriter().write(results.toString());

        } catch (SQLException e) {
            resp.sendError(500, "Database error");
        } finally {
            if (stmt != null) try { stmt.close(); } catch (SQLException e) {}
            if (conn != null) try { conn.close(); } catch (SQLException e) {}
        }
    }

    private boolean isValidReportType(String type) {
        return type != null && (type.equals("daily") || type.equals("weekly") ||
               type.equals("monthly") || type.equals("quarterly"));
    }

    private String sanitizeDateRange(String range) {
        // Allow: 7 days, 30 days, 1 year, etc.
        return range.replaceAll("[^0-9a-z ]", "");
    }

    private Connection getConnection() throws SQLException {
        return DriverManager.getConnection(
            System.getenv("DB_URL"),
            System.getenv("DB_USER"),
            System.getenv("DB_PASS")
        );
    }
}
